package id.my.wandidev.klyndro.net

import id.my.wandidev.klyndro.crypto.Fingerprint
import java.net.URI
import java.net.URLDecoder
import java.nio.charset.StandardCharsets

/**
 * Decodes `klyndro://pair?v=1&host=...&port=...&fp=...` QR payloads generated by the Mac.
 */
data class PairingQRPayload(
    val host: String,
    val port: Int,
    val fingerprint: Fingerprint,
    val name: String? = null
) {
    companion object {
        const val CURRENT_VERSION = 1
        private const val MAX_NAME_CHARS = 64

        fun parse(raw: String): PairingQRPayload? {
            val trimmed = raw.trim()
            if (trimmed.isEmpty()) return null

            val uri = runCatching { URI(trimmed) }.getOrNull() ?: return null
            if (!uri.scheme.equals("klyndro", ignoreCase = true)) return null
            if (!uri.host.equals("pair", ignoreCase = true)) return null

            val rawQuery = uri.rawQuery ?: return null
            val params = LinkedHashMap<String, String>()
            for (pair in rawQuery.split('&')) {
                if (pair.isEmpty()) continue
                val eq = pair.indexOf('=')
                if (eq <= 0) continue
                val key = decodeQueryComponent(pair.substring(0, eq)) ?: continue
                val value = decodeQueryComponent(pair.substring(eq + 1)) ?: continue
                params[key] = value
            }

            if (params["v"] != CURRENT_VERSION.toString()) return null
            val host = params["host"]?.takeIf { isValidHost(it) } ?: return null
            val port = params["port"]?.toIntOrNull()?.takeIf { it in 1..65535 } ?: return null
            val fingerprint = params["fp"]?.let { Fingerprint.parse(it) } ?: return null
            val name = params["name"]?.trim()?.takeIf { it.isNotEmpty() }?.take(MAX_NAME_CHARS)

            return PairingQRPayload(
                host = host,
                port = port,
                fingerprint = fingerprint,
                name = name
            )
        }

        private fun decodeQueryComponent(part: String): String? = runCatching {
            URLDecoder.decode(part, StandardCharsets.UTF_8.name())
        }.getOrNull()

        private fun isValidHost(host: String): Boolean {
            if (host.isEmpty() || host.length > 253) return false
            if (host.any { it.isWhitespace() || it == '/' || it == ':' }) return false
            return !host.startsWith('.') && !host.endsWith('.') && !host.contains("..")
        }
    }
}
